let current='home',lastRouteHash='';function route(){let [r,id]=location.hash.slice(1).split('/');id=id?.toUpperCase();if(r==='report'&&(lastRouteHash!==location.hash||current!=='report')){draft={step:id&&getBin(id)?2:1,bin:id&&getBin(id)?id:'',issue:'',note:'',ref:''}}lastRouteHash=location.hash;return [...dashRoutes,'home','how','technology','councils','about','report'].includes(r)?r:'home'}function render(scroll=false){stopScanner();destroyNetworkMap();const previous=current;current=route();if(current!=='map'&&current!=='dashboard')selectedNetworkBin='';if(current==='report'&&previous!=='report'&&draft.step===4)draft={step:1,bin:'',issue:'',note:'',ref:''};let isDash=dashRoutes.includes(current);$('#shell').innerHTML=isDash?'':nav(current);$('#footer').innerHTML=isDash?'':footer();main.innerHTML=isDash?dashShell(current):({home,how,technology,councils,about,report})[current]();document.title=`${isDash?labels[current]:({home:'Smarter bins. Cleaner streets.',how:'How it works',technology:'Technology',councils:'For councils',about:'About the demo',report:'Report a bin issue'})[current]} — BinLink`;if(isDash&&(current==='map'||current==='dashboard'))mountNetworkMap();if(scroll){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}}
window.addEventListener('hashchange',()=>{if(modal.open)modal.close();render(true)});function reportRerender(){stopScanner();main.innerHTML=report();window.scrollTo({top:document.querySelector('.report-main').getBoundingClientRect().top+window.scrollY-85,behavior:'instant'});let target=main.querySelector('.form-title,.success h2');if(target){target.tabIndex=-1;target.focus({preventScroll:true})}}
function captureDraft(){let f=$('#report-form');if(!f)return;let data=new FormData(f);if(data.has('issue'))draft.issue=data.get('issue');if(data.has('note'))draft.note=data.get('note')}
document.addEventListener('submit',e=>{if(e.target.id==='report-form'){e.preventDefault();const data=new FormData(e.target);if(draft.step===1){if(data.get('bin'))draft.bin=data.get('bin');if(!draft.bin){toast('Choose a bin to continue.');return}draft.step=2}else if(draft.step===2||draft.step===3){captureDraft();if(!draft.issue||!getBin(draft.bin))return;const id='BLR-'+state.next++;state.reports.unshift({id,bin:draft.bin,issue:draft.issue,note:draft.note,status:'New',date:new Date().toISOString()});save();draft.ref=id;draft.step=4}reportRerender()}else if(e.target.id==='status-form'){e.preventDefault();const r=state.reports.find(r=>r.id===e.target.dataset.id);if(r){r.status=new FormData(e.target).get('status');save();modal.close();render();toast('Report status updated.')}}});
document.addEventListener('input',e=>{if(e.target.id==='bin-search'){let b=getBin(draft.bin);if(b&&!`${b.id} ${b.name} ${b.area}`.toLowerCase().includes(e.target.value.toLowerCase()))draft.bin='';$('#bin-options').innerHTML=binChoices(e.target.value)}if(e.target.id==='table-search'){filters[current].q=e.target.value;$('#table-results').innerHTML=current==='bins'?binTable(getRows(current)):reportTable(getRows(current))}if(e.target.name==='note')draft.note=e.target.value});document.addEventListener('change',e=>{if(e.target.name==='bin')draft.bin=e.target.value;if(e.target.name==='issue')draft.issue=e.target.value;if(e.target.id==='table-filter'){filters[current].status=e.target.value;$('#table-results').innerHTML=current==='bins'?binTable(getRows(current)):reportTable(getRows(current))}});
document.addEventListener('click',e=>{let menu=e.target.closest('#menu');if(menu){let open=$('#navlinks').classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');return}let t=e.target.closest('[data-action]');if(!t){if($('#sidebar')?.classList.contains('open')&&!e.target.closest('#sidebar')){$('#sidebar').classList.remove('open');document.querySelector('[data-action="sidebar"]')?.setAttribute('aria-expanded','false')}return}let a=t.dataset.action,id=t.dataset.id;switch(a){case 'sidebar':{let open=$('#sidebar').classList.toggle('open');t.setAttribute('aria-expanded',open);break}case 'close':modal.close();break;case 'bin-detail':binDetail(id);break;case 'report-detail':reportDetail(id);break;case 'collect':{let b=getBin(id);if(b){b.fill=0;save();modal.close();render();toast(`${b.name} marked collected.`)}break}case 'report-bin':modal.close();selectScannedBin(id);break;case 'report-back':captureDraft();draft.step--;reportRerender();break;case 'new-report':resetReport();break;case 'start-scan':startScanner();break;case 'stop-scan':stopScanner();setScanStatus('Camera stopped.');break;case 'choose-sample':selectScannedBin(id);break;case 'show-bin-qr':showBinQR(id);break;case 'copy-bin-link':copyBinLink(id);break;case 'simulate':state.bins.forEach(b=>{if(b.online){b.fill=Math.min(100,b.fill+2+Math.floor(Math.random()*4));b.battery=Math.max(0,b.battery-1)}});save();render();toast('Simulated sensor readings refreshed.');break;case 'clear-filter':filters[current]={q:'',status:'all'};render();break;case 'export-bins':csv('bins');break;case 'export-reports':csv('reports');break;case 'reset':showModal('Reset demonstration?',`<p>This will remove locally added reports and restore the original sample data.</p><div class="modal-footer"><button class="btn outline" data-action="close">Cancel</button><button class="btn primary" data-action="confirm-reset">Reset demo</button></div>`);break;case 'confirm-reset':state={bins:clone(seedBins),reports:clone(seedReports),next:1043};draft={step:1,bin:'',issue:'',note:'',ref:''};filters={bins:{q:'',status:'all'},reports:{q:'',status:'all'}};save();modal.close();render();toast('Original demo data restored.');break}});modal.addEventListener('click',e=>{if(e.target===modal){const rect=modal.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)modal.close()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar')?.classList.contains('open')){$('#sidebar').classList.remove('open');document.querySelector('[data-action="sidebar"]')?.setAttribute('aria-expanded','false')}});if(!location.hash){try{const id=new URL(location.href).searchParams.get('bin')?.toUpperCase();if(getBin(id)){const u=new URL(location.href);u.searchParams.delete('bin');u.hash='report/'+id;history.replaceState(null,'',u.href)}}catch(e){}}render();
